/**
 * Generates src/services/mock/RealInventory.ts from data/maestros.csv and data/obras.csv.
 *
 *   npm run seed:obras
 *
 * SeedData builds the simulated database from that file: masters, stores and works with their
 * photos in public/obras (run "npm run import:obras" first so the photos exist). Catalog values go
 * as codes (shape, colors, figures, style); SeedData turns them into ids. Do not edit the output by hand.
 */
import { existsSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Inventory } from "./lib/Inventory.ts";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const output = join(root, "src", "services", "mock", "RealInventory.ts");

const inventory = new Inventory(join(root, "data"));
const missing = inventory.works.flatMap((work) => work.photos).filter((photo) => !existsSync(join(root, "public", photo.output)));
if (missing.length) {
  console.error(`Missing photos (run npm run import:obras first):\n${missing.map((photo) => `  public/${photo.output}`).join("\n")}`);
  process.exit(1);
}

const masters = inventory.masters.map((master) => ({
  key: master.key,
  name: master.name,
  storeEs: master.storeEs,
  storeEn: master.storeEn,
  city: master.city,
  avatar: master.avatar,
  biographyEs: master.biographyEs,
  biographyEn: master.biographyEn,
}));

const works = inventory.works.map((work) => ({
  masterKey: work.masterKey,
  slug: work.slug,
  titleEs: work.titleEs,
  titleEn: work.titleEn,
  descriptionEs: work.descriptionEs,
  descriptionEn: work.descriptionEn,
  photos: work.photos.map((photo) => `/${photo.output}`),
  shape: work.shape,
  colors: work.colors,
  motifs: work.motifs,
  style: work.style,
  price: work.price,
  currency: work.currency,
  provisionalPrice: work.provisionalPrice,
  widthCm: work.widthCm,
  heightCm: work.heightCm,
  depthCm: work.depthCm,
  saleMode: work.saleMode,
  stock: work.stock,
}));

const json = (value: unknown) => JSON.stringify(value, null, 2);

const source = `// Generated by scripts/generate-seed.ts from data/maestros.csv and data/obras.csv. Do not edit by hand:
// change the CSV files and run "npm run seed:obras".

export interface RealMaster {
  /** Short key: e-mail (<key>@museo.co), store slug and photo folder. */
  key: string;
  name: string;
  storeEs: string;
  storeEn: string;
  city: string;
  /** Avatar catalog code. */
  avatar: string;
  biographyEs: string;
  biographyEn: string;
}

export interface RealWork {
  masterKey: string;
  slug: string;
  titleEs: string;
  titleEn: string;
  descriptionEs: string;
  descriptionEn: string;
  /** Photo URLs; the first one is the main photo. */
  photos: string[];
  /** Catalog codes. */
  shape: string;
  colors: string[];
  motifs: string[];
  style: string;
  /** Sale price, or the base price when the work goes to auction. */
  price: number | null;
  currency: string;
  /** True while the price is a placeholder and not the master's real price. */
  provisionalPrice: boolean;
  widthCm: number | null;
  heightCm: number | null;
  depthCm: number | null;
  saleMode: "SALE" | "AUCTION";
  stock: number;
}

/** The real masters and their works, in the inventory's order (the order gives the ids). */
export class RealInventory {
  static readonly masters: readonly RealMaster[] = ${json(masters)};

  static readonly works: readonly RealWork[] = ${json(works)};
}
`;

writeFileSync(output, source, "utf8");
console.log(`${masters.length} masters and ${works.length} works written to src/services/mock/RealInventory.ts`);
